firmware:
const int SW_PIN = 15;
const int LED_PIN = 2;
int last = -1;

void setup() {
  Serial.begin(115200);
  pinMode(SW_PIN, INPUT_PULLUP);
  pinMode(LED_PIN, OUTPUT);
  digitalWrite(LED_PIN, LOW);
}

void loop() {
  int on = digitalRead(SW_PIN) == LOW ? 1 : 0;
  if (on != last) {
    digitalWrite(LED_PIN, on ? HIGH : LOW);
    Serial.println(on ? "MODE=ON" : "MODE=OFF");
    last = on;
  }
  delay(20);
}
